if (document.getElementById('yahoo-directory-grid')) return;

const grid = document.createElement('div');
grid.id = 'yahoo-directory-grid';
grid.style.cssText = `
  max-width: 760px;
  margin: 24px auto;
  padding: 0 16px;
  font-family: inherit;
`;

const categories = [
  { label: '📰  News',        url: 'https://news.yahoo.com',          desc: 'Top headlines & breaking news',      color: '#6001d2' },
  { label: '💰  Finance',     url: 'https://finance.yahoo.com',        desc: 'Markets, stocks & business news',    color: '#0078d4' },
  { label: '🏆  Sports',      url: 'https://sports.yahoo.com',         desc: 'Scores, stats & highlights',         color: '#d63031' },
  { label: '🌤  Weather',     url: 'https://weather.yahoo.com',        desc: 'Forecasts & radar maps',             color: '#00b894' },
  { label: '🎬  Entertainment', url: 'https://www.yahoo.com/entertainment', desc: 'Movies, TV & celebrity news',  color: '#e17055' },
  { label: '🏥  Health',      url: 'https://health.yahoo.com',         desc: 'Wellness tips & medical news',       color: '#00cec9' },
  { label: '🔬  Science',     url: 'https://www.yahoo.com/science',    desc: 'Discoveries & tech research',        color: '#6c5ce7' },
  { label: '✈️  Travel',      url: 'https://www.yahoo.com/travel',     desc: 'Destinations & travel deals',        color: '#fdcb6e' },
  { label: '🛒  Shopping',    url: 'https://shopping.yahoo.com',       desc: 'Deals, reviews & product picks',     color: '#e84393' },
  { label: '🎮  Games',       url: 'https://www.yahoo.com/games',      desc: 'Puzzles, trivia & games',            color: '#2d3436' },
  { label: '⚖️  Politics',    url: 'https://www.yahoo.com/politics',   desc: 'Policy, elections & government',     color: '#b2395c' },
  { label: '🌍  World',       url: 'https://www.yahoo.com/world-news', desc: 'International news & events',        color: '#0984e3' },
];

const heading = document.createElement('h2');
heading.textContent = 'Where would you like to go?';
heading.style.cssText = `
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--color-primary, #1a1a1a);
  margin-bottom: 18px;
  margin-top: 4px;
  letter-spacing: -0.01em;
`;
grid.appendChild(heading);

const gridWrap = document.createElement('div');
gridWrap.style.cssText = `
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 14px;
`;

categories.forEach(cat => {
  const a = document.createElement('a');
  a.href = cat.url;
  a.style.cssText = `
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    padding: 18px 16px 14px;
    background: var(--color-primary-bg, #ffffff);
    border: 2px solid transparent;
    border-radius: 14px;
    text-decoration: none;
    box-shadow: 0 1px 6px rgba(0,0,0,0.08);
    transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.12s ease;
    cursor: pointer;
    position: relative;
    overflow: hidden;
  `;

  const accent = document.createElement('div');
  accent.style.cssText = `
    width: 28px;
    height: 4px;
    border-radius: 2px;
    background: ${cat.color};
    margin-bottom: 10px;
  `;

  const label = document.createElement('span');
  label.textContent = cat.label;
  label.style.cssText = `
    font-size: 1rem;
    font-weight: 700;
    color: var(--color-primary, #1a1a1a);
    display: block;
    margin-bottom: 5px;
    line-height: 1.3;
  `;

  const desc = document.createElement('span');
  desc.textContent = cat.desc;
  desc.style.cssText = `
    font-size: 0.75rem;
    color: var(--color-secondary, #666);
    font-weight: 400;
    line-height: 1.4;
  `;

  a.appendChild(accent);
  a.appendChild(label);
  a.appendChild(desc);

  a.addEventListener('mouseover', () => {
    a.style.borderColor = cat.color;
    a.style.boxShadow = `0 4px 16px rgba(0,0,0,0.12)`;
    a.style.transform = 'translateY(-2px)';
  });
  a.addEventListener('mouseout', () => {
    a.style.borderColor = 'transparent';
    a.style.boxShadow = '0 1px 6px rgba(0,0,0,0.08)';
    a.style.transform = 'translateY(0)';
  });

  gridWrap.appendChild(a);
});

grid.appendChild(gridWrap);

// Insert after the convenience bar wrapper
element.appendChild(grid);
